{"file_text": "@using sv_ccb4769bce0c4661b9ddc2b96fd46c4d.Models

<div class="step-content">
    <h3>Review & Submit</h3>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h4>Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will be in touch soon.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <div class="review-section card p-3 mb-3">
            <div class="d-flex justify-content-between align-items-center">
                <h5>Personal Information</h5>
                <button type="button" class="btn btn-link btn-sm" @onclick="() => OnEdit.InvokeAsync(0)">Edit</button>
            </div>
            @if (Personal is not null)
            {
                <dl class="row mb-0">
                    <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@Personal.FullName</dd>
                    <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@Personal.Email</dd>
                    <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@Personal.Phone</dd>
                    <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@Personal.Address</dd>
                </dl>
            }
        </div>

        <div class="review-section card p-3 mb-3">
            <div class="d-flex justify-content-between align-items-center">
                <h5>Work History</h5>
                <button type="button" class="btn btn-link btn-sm" @onclick="() => OnEdit.InvokeAsync(1)">Edit</button>
            </div>
            @if (Work is not null)
            {
                @foreach (var entry in Work.Entries)
                {
                    <div class="mb-2 ps-2 border-start">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <small class="text-muted">
                            @entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mb-0 mt-1">@entry.Description</p>
                        }
                    </div>
                }
            }
        </div>

        <div class="review-section card p-3 mb-3">
            <div class="d-flex justify-content-between align-items-center">
                <h5>References</h5>
                <button type="button" class="btn btn-link btn-sm" @onclick="() => OnEdit.InvokeAsync(2)">Edit</button>
            </div>
            @if (References is not null)
            {
                @foreach (var r in References)
                {
                    <div class="mb-2 ps-2 border-start">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        <small>@r.Email &bull; @r.Phone</small>
                    </div>
                }
            }
        </div>

        <div class="review-section card p-3 mb-3">
            <div class="d-flex justify-content-between align-items-center">
                <h5>Cover Letter</h5>
                <button type="button" class="btn btn-link btn-sm" @onclick="() => OnEdit.InvokeAsync(3)">Edit</button>
            </div>
            <p class="mb-0" style="white-space: pre-wrap;">@CoverLetter</p>
        </div>

        <div class="step-buttons">
            <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
            <button type="button" class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @if (IsSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Submit Application
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public WorkHistory? Work { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback<int> OnEdit { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    public bool IsSubmitted { get; set; }
    public int? ApplicationId { get; set; }
    public bool IsSubmitting { get; set; }
    public string? ErrorMessage { get; set; }

    // Called by parent after successful submission
    public void ShowConfirmation(int applicationId)
    {
        ApplicationId = applicationId;
        IsSubmitted = true;
        StateHasChanged();
    }

    public void ShowError(string message)
    {
        ErrorMessage = message;
        IsSubmitting = false;
        StateHasChanged();
    }

    private async Task HandleSubmit()
    {
        ErrorMessage = null;
        IsSubmitting = true;
        await OnSubmit.InvokeAsync();
    }
}
