@using sv_ccb4769bce0c4661b9ddc2b96fd46c4d.Models

<div class="step-content">
    <h3>References</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <div class="reference-entry card p-3 mb-3">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h5 class="mb-0">Reference @(index + 1)</h5>
                @if (References.Count > 2)
                {
                    <button type="button" class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>

            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Name *</label>
                    <input type="text" class="form-control" value="@References[index].Name"
                           @onchange="e => UpdateReference(index, References[index] with { Name = (string?)e.Value ?? string.Empty })" />
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Relationship *</label>
                    <input type="text" class="form-control" value="@References[index].Relationship"
                           @onchange="e => UpdateReference(index, References[index] with { Relationship = (string?)e.Value ?? string.Empty })" />
                </div>
            </div>
            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Email *</label>
                    <input type="email" class="form-control" value="@References[index].Email"
                           @onchange="e => UpdateReference(index, References[index] with { Email = (string?)e.Value ?? string.Empty })" />
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Phone *</label>
                    <input type="tel" class="form-control" value="@References[index].Phone"
                           @onchange="e => UpdateReference(index, References[index] with { Phone = (string?)e.Value ?? string.Empty })" />
                </div>
            </div>
        </div>
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddReference">
            + Add Reference
        </button>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference>? Model { get; set; }
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<Reference> References = new();
    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        if (Model is not null && Model.Count > 0)
        {
            References = Model.ToList();
        }
        else if (References.Count == 0)
        {
            References.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
            References.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
        }
    }

    private void UpdateReference(int index, Reference updated)
    {
        References[index] = updated;
    }

    private void RemoveReference(int index)
    {
        References.RemoveAt(index);
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync(References.ToList());
    }
}

