+.step-indicator {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    gap: 0;
+}
+
+.step {
+    display: flex;
+    flex-direction: column;
+    align-items: center;
+    cursor: default;
+    padding: 0 0.5rem;
+}
+
+.step.completed {
+    cursor: pointer;
+}
+
+.step-circle {
+    width: 36px;
+    height: 36px;
+    border-radius: 50%;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    font-weight: bold;
+    font-size: 0.875rem;
+    border: 2px solid #dee2e6;
+    background: white;
+    color: #6c757d;
+    transition: all 0.2s;
+}
+
+.step.active .step-circle {
+    background: #0d6efd;
+    border-color: #0d6efd;
+    color: white;
+}
+
+.step.completed .step-circle {
+    background: #198754;
+    border-color: #198754;
+    color: white;
+}
+
+.step.dimmed .step-circle {
+    opacity: 0.5;
+}
+
+.step-label {
+    font-size: 0.75rem;
+    margin-top: 0.25rem;
+    text-align: center;
+    color: #6c757d;
+    white-space: nowrap;
+}
+
+.step.active .step-label {
+    color: #0d6efd;
+    font-weight: 600;
+}
+
+.step.completed .step-label {
+    color: #198754;
+}
+
+.step.dimmed .step-label {
+    opacity: 0.5;
+}
+
+.step-connector {
+    flex: 1;
+    height: 2px;
+    background: #dee2e6;
+    min-width: 2rem;
+    margin-bottom: 1.25rem;
+}
+
+.step-connector.completed {
+    background: #198754;
+}
+
+/* Step Content */
+.step-content {
+    background: white;
+    border: 1px solid #dee2e6;
+    border-radius: 0.5rem;
+    padding: 2rem;
+}
+
+.step-buttons {
+    display: flex;
+    gap: 0.75rem;
+    justify-content: flex-end;
+    margin-top: 1.5rem;
+    padding-top: 1rem;
+    border-top: 1px solid #dee2e6;
+}
+
+/* Work Entry */
+.work-entry-editor {
