@using sv_ccb4769bce0c4661b9ddc2b96fd46c4d.Models

<div class="work-entry-editor">
    <div class="entry-header">
        <h5>Position @(Index + 1)</h5>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="mb-3">
        <label class="form-label">Company Name *</label>
        <input type="text" class="form-control" value="@Entry.Company"
               @onchange="HandleCompanyChange" />
    </div>

    <div class="mb-3">
        <label class="form-label">Job Title *</label>
        <input type="text" class="form-control" value="@Entry.Title"
               @onchange="HandleTitleChange" />
    </div>

    <div class="row mb-3">
        <div class="col-md-5">
            <label class="form-label">Start Date *</label>
            <input type="date" class="form-control" value="@FormatDate(Entry.StartDate)"
                   @onchange="HandleStartDateChange" />
        </div>
        <div class="col-md-5">
            <label class="form-label">End Date</label>
            <input type="date" class="form-control" value="@FormatNullableDate(Entry.EndDate)"
                   disabled="@IsCurrent"
